            bounds[0] = value;
            return this;
        }

        public Config idealWidth(float value) {
            return bound(1, value);
        }

        public Config idealWidth(Signal<Float> value) {
            bounds[1] = value;
            return this;
        }

        public Config maxWidth(float value) {
