//! Diff-based reactive emitter.
//!
//! The engine holds the application's retained view tree and emits the
//! declarative structure as `TREE`/`PARAMETER` opcodes into the 16-byte ring
//! buffer (VStack, HStack, Text, spacing, padding, alignment). It does not
//! compute rects or layout; native renderers lay out their own elements.
//!
//! Emission is diff-based: on each `emit` the engine compares the current tree
//! against a snapshot of what it last emitted and writes only the opcodes for
//! nodes that actually changed. An unchanged tree emits zero opcodes.
//!
//! The emit pass performs zero dynamic heap allocations in the steady state.
//!
//! ## Signals
//!
//! Nodes may bind their text or a property to a [`crate::SignalId`]. The engine
//! resolves those bindings during emit (recording the dependency) and re-emits
//! only the affected nodes on [`Engine::set_signal`] — no full tree walk.

use alloc::borrow::ToOwned;
use alloc::collections::BTreeMap;
use alloc::string::{String, ToString};
use alloc::vec;
use alloc::vec::Vec;

use pathland_core::{category, meta, value_type, value_type_for, window_field, WindowMeta};
use pathland_core::{Guest, Opcode};

use crate::node::{component_type_id, Component, Node};
use crate::signal::{Dep, Runtime, Signal, SignalId, SignalValue, SignalValueKind, WritableSignal};
use crate::window::WindowMetadata;

/// Encode a `LIST` property's arena entry: `[u32 count][f32 × count]`
/// (spec/OPCODE.md §Value types — a `FIT_QUERY` threshold table).
fn encode_list(values: &[f32]) -> Vec<u8> {
    let mut bytes = vec![0u8; 4 + 4 * values.len()];
    bytes[0..4].copy_from_slice(&(values.len() as u32).to_le_bytes());
    for (i, value) in values.iter().enumerate() {
        let o = 4 + 4 * i;
        bytes[o..o + 4].copy_from_slice(&value.to_bits().to_le_bytes());
    }
    bytes
}

/// Per-node state the engine remembers from the last emission.
#[derive(Debug, Clone, PartialEq)]
struct SnapshotNode {
    component_type: u16,
    parent: Option<u32>,
    index: usize,
    text: Option<String>,
    properties: BTreeMap<u16, u32>,
    /// Last-emitted `STRING` properties: property → (value, arena offset). The
    /// arena offset is reused across passes so an unchanged string never
    /// re-allocates into the bump arena.
    string_properties: BTreeMap<u16, (String, u32)>,
    /// Last-emitted `LIST` properties: property → (values, arena offset). The
    /// arena offset is reused across passes so an unchanged list never
    /// re-allocates into the bump arena.
    list_properties: BTreeMap<u16, (Vec<f32>, u32)>,
    /// Last-emitted `DESIGN_TOKEN` refs: property → (token path, arena offset).
    /// The arena offset is reused across passes so an unchanged ref never
    /// re-allocates into the bump arena.
    token_refs: BTreeMap<u16, (String, u32)>,
    /// Generation stamp set on each emit pass; used to detect deleted nodes.
    gen: u64,
}

/// Result of an emission pass.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EmitResult {
    /// Number of opcodes written to the ring.
    pub opcodes: usize,
}

/// The diff-based reactive emitter.
///
/// `Engine` keeps the snapshot of what was last emitted and owns the signal
/// store. Calling `emit` with a (possibly mutated) retained tree writes only
/// the delta opcodes; `set_signal` writes deltas for only the bound nodes.
pub struct Engine {
    /// nodeId to last emitted state (a preallocated slab; node ids are dense).
    snapshot: Vec<Option<SnapshotNode>>,
    /// Monotonic generation stamp for the current pass.
    gen: u64,
    /// Reactive signal runtime (values + computed/effects + node dependencies).
    store: Runtime,
    /// Window/surface metadata signal bindings (`META::SET_WINDOW_METADATA`).
    window: WindowMetadata,
    /// The last window metadata written to the wire (dedupe / clear detection).
    window_emitted: WindowMeta,
}

impl Default for Engine {
    fn default() -> Self {
        Self::new()
    }
}

impl Engine {
    pub fn new() -> Self {
        Self {
            snapshot: Vec::new(),
            gen: 0,
            store: Runtime::new(),
            window: WindowMetadata::new(),
            window_emitted: WindowMeta::new(),
        }
    }

    /// The shared reactive runtime (for creating typed signals / computeds).
    pub fn runtime(&self) -> Runtime {
        self.store.clone()
    }

    /// Reconcile `root` against the snapshot, emitting only changed opcodes.
    pub fn emit(
        &mut self,
        root: &Node,
        guest: &mut Guest<'_>,
    ) -> Result<EmitResult, pathland_core::RingError> {
        self.gen = self.gen.wrapping_add(1);
        // Rebuild the signal->node dependency index from scratch; reconcile
        // re-adds the bindings this tree actually uses, so stale subscriptions
        // vanish.
        self.store.clear_node_deps();
        // Window metadata is renderer-global, not part of the tree: emit the
        // initial values (and any rebind/clear) before the node opcodes.
        let mut out = self.emit_window_metadata(guest)?;
        self.reconcile_node(root, None, 0, guest, &mut out)?;

        for (id, slot) in self.snapshot.iter_mut().enumerate() {
            if let Some(s) = slot {
                if s.gen != self.gen {
                    guest.delete_node(id as u32)?;
                    out += 1;
                    *slot = None;
                }
            }
        }
        Ok(EmitResult { opcodes: out })
    }

    /// Number of nodes tracked in the snapshot (diagnostics).
    pub fn tracked_nodes(&self) -> usize {
        self.snapshot.iter().filter(|s| s.is_some()).count()
    }

    /// Bind the window/surface presentation metadata
    /// (`META::SET_WINDOW_METADATA`): title, description, locale. Values are
    /// signal-backed, so a route can drive them from a computed. The next
    /// [`Engine::emit`] writes the initial values; a subsequent
    /// [`Engine::set_signal`] writes only the changed field.
    pub fn bind_window_metadata(&mut self, metadata: WindowMetadata) {
        self.window = metadata;
    }

    /// Bind one window-metadata field to a signal (the flat/C-ABI form of
    /// [`Engine::bind_window_metadata`]).
    pub fn bind_window_field(&mut self, field: u16, signal: SignalId) {
        self.window.set_signal(field, signal);
    }

    /// Emit changed window-metadata fields. Unchanged fields write nothing; a
    /// field that became unset writes an empty string (clear).
    fn emit_window_metadata(
        &mut self,
        guest: &mut Guest<'_>,
    ) -> Result<usize, pathland_core::RingError> {
        let mut out = 0usize;
        for field in window_field::ALL {
            let value = self.window.signal(field).and_then(|id| {
                let value = self.store.get(id);
                value.to_text().map(ToOwned::to_owned)
            });
            let previous = self.window_emitted.get(field).map(ToOwned::to_owned);
            if value == previous {
                continue;
            }
            let text = value.as_deref().unwrap_or("");
            let offset = guest.alloc_str(text).map_err(|_| pathland_core::RingError::Full)?;
            guest.push_opcode(Opcode::new(
                category::META,
                meta::SET_WINDOW_METADATA,
                0,
                field as u32,
                offset,
                0,
            ))?;
            self.window_emitted.set(field, text);
            out += 1;
        }
        Ok(out)
    }

