import dev.pathland.view.emit.PathlandNode;

import java.util.Objects;
import java.util.function.Supplier;

/**
 * A composable view. Composite views declare their subtree with
 * {@link #body()}; the library's primitives (leaves, stacks, controls) instead override
 * {@link #renderNode(Environment)} to materialize a {@link PathlandNode}. The interface
 * is open: the library ships the leaf primitives and modifier wrappers, and
 * application code (Quarkus, Spring Boot, desktop) defines its own views by
 * implementing {@code View} directly.
 *
 * <p>{@link #body()} / {@link #renderNode(Environment)} form a tracked render
 * computation: a signal read during them subscribes the owning component, and a
 * later write re-renders that component and diffs its subtree. The render body must
 * be pure/idempotent and must not write signals. Non-signal reads are mount-time
 * only. {@link #render(Environment)} is the emitter entry point and must not be
 * overridden.
 *
 * <p>Modifiers are {@link ViewModifier} values applied with {@link #modifiers(ViewModifier...)}
 * — built-in and application-authored modifiers share one mechanism (spec DSL.md
 * §5.6), applied innermost-first. There is no per-modifier factory sugar on this
 * interface. Constructor (structural/layout) properties are passed to the view
 * constructors and are never chainable.
 */
public interface View {

    /**
     * The base marker for a view's **value config** ({@code V.Config}). The
     * config is populated by the static {@code View.make(Consumer<Config>)}
     * factory and is the same type a style's {@code makeBody(Config)} reads
     * (spec DSL.md §5.7).
     */
    interface Config {
    }

    /**
     * Declarative composition: a composite view returns its subtree here. Primitives
     * return {@code this} (the identity body) and instead override
     * {@link #renderNode(Environment)}.
     */
    default View body() {
        return this;
    }

    /**
     * The emitter entry point: render this view as a tracked component slot. Called by
     * a parent view for each child ({@code child.render(env)}). The emitter installs a
     * {@link dev.pathland.view.emit.Emitter#current() current} render context; direct
     * calls outside an emitter fall back to {@link #renderNode(Environment)}.
     */
    default PathlandNode render(Environment env) {
        dev.pathland.view.emit.Emitter emitter = dev.pathland.view.emit.Emitter.current();
        return emitter == null ? renderNode(env) : emitter.renderView(this, env);
    }

    /**
     * The root-chain render: composite views resolve {@link #body()} and delegate to
     * the resolved view's {@code renderNode} (same component); wrappers delegate to
     * their inner view's {@code renderNode}; primitives build a {@link PathlandNode}
     * and call {@code child.render(env)} for child views (new component slots).
     */
    default PathlandNode renderNode(Environment env) {
        dev.pathland.view.state.PersistentState state = env.state();
        if (state != null) {
            state.connect(this); // wire this view's State fields (idempotent)
        }
        View resolved = body();
        if (resolved != this) {
            return resolved.renderNode(env);
        }
        throw new UnsupportedOperationException(
                getClass().getName() + " must override body() (composite) or renderNode() (primitive)");
    }

    /**
     * Wrap this view in one or more modifiers ({@code .modifier}), applied
     * innermost-first: {@code modifiers(A, B, C)} ≡ {@code modifiers(A).modifiers(B).modifiers(C)}.
     * A single modifier is the common case; an empty call returns {@code this}.
     * {@code with(...)} is for values only — modifiers always go through this
     * {@code modifiers(...)} operation.
     */
    default View modifiers(ViewModifier... modifiers) {
        View result = this;
        for (ViewModifier modifier : modifiers) {
            result = Modified.apply(result, modifier);
        }
        return result;
    }

    /**
     * A reactive subtree from a supplier: the inline form of control flow. The supplier
     * is read during this component's tracked render, so any signal it reads re-renders
     * the slot; the selected view is a child component slot.
     *
     * <pre>{@code
     * VStack.make().children(
     *     View.of(() -> mode.get() == Mode.LIST ? listView : gridView));
     * }</pre>
     */
    static View of(Supplier<View> content) {
        return new ReactiveSlotView(Objects.requireNonNull(content, "content"));
    }
}

package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;
import dev.pathland.view.signal.Signal;
import dev.pathland.view.signal.Signals;

import java.util.List;
import java.util.function.Consumer;

/**
 * An interactive button ({@code Button}). Accepts an arbitrary child view as
 * the label. The control owns the native {@code BUTTON} node and wires the action on
 * it; the active {@link ButtonStyle} (spec DSL.md §5.7) supplies the button's content
 * as the button node's child.
 *
 * <p>Content precedence (spec DSL.md §4): a child supplied via {@code .children(…)}
 * wins, then a {@code title} value, then the style's own content.
 */
public final class Button implements View, Configurable<Button.Config>, ChildrenView {

    /** {@link Button} values. */
    public static final class Config implements View.Config {

        private Runnable action;
        private Signal<String> title;

        /** Set the tap action. */
        public Config action(Runnable action) {
            this.action = action;
            return this;
        }

        /** Set a static plain text title (used when no child is supplied). */
        public Config title(String title) {
            this.title = Signals.constant(title);
            return this;
        }

        /** Bind the plain text title to a signal. */
        public Config title(Signal<String> title) {
            this.title = title;
            return this;
        }
    }

    private final Config config;
    private List<View> children = List.of();

    private Button(Config config, List<View> children) {
        this.config = config;
        this.children = children;
    }

    /** Configure the button's values. */
/** An empty Button (no values). */
    public static ViewBuilder<Button, Config> make() {
        return new ViewBuilder<>(new Button(new Config(), List.of()));
    }

    public static ViewBuilder<Button, Config> make(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new Button(config, List.of()));
    }

    /** Supply the button's label. */
    public static ViewBuilder<Button, Config> children(View... children) {
        return new ViewBuilder<>(new Button(new Config(), List.of())).children(children);
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public void setChildren(List<View> children) {
        this.children = List.copyOf(children);
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        // The control owns the native BUTTON shell + the action; the style supplies
        // the content (the decorated label) as the shell's child. The label keeps its
        // own component(s) and layout (Composite Override Mode, PRIMITIVES.md §2).
        View label = !children.isEmpty()
                ? children.get(0)
                : (config.title != null ? Text.make(t -> t.text(config.title)) : null);

        PathlandNode node = new PathlandNode(Components.BUTTON);
        ButtonStyle style = env.buttonStyle();
        View content = style.makeBody(new ButtonStyle.Configuration(label));
        if (content != null && content != EmptyContent.INSTANCE) {
            node.children.add(content.render(env));
        }
        Object existing = node.properties.get(Properties.EVENT_LISTENERS);
        int mask = existing instanceof Integer i ? i : 0;
        node.properties.put(
                Properties.EVENT_LISTENERS,
                mask | Commands.Listeners.POINTER_DOWN | Commands.Listeners.POINTER_UP);
        node.tapActions.add(config.action);
        return node;
    }
}
package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;

import java.util.function.Consumer;

/**
 * A video playback **surface**: a view that renders a {@link MediaController}'s
 * video output in its own box (spec/MEDIA.md). It references the controller —
 * the relationship is a reference, not a parent/child edge — so playback survives
 * structural swaps (a {@code SIZE_THAT_FITS} band change re-emits only this
 * surface; the controller's playback is untouched).
 *
 * <p>Playback is **renderer-native by default** (the web renderer emits
 * {@code <video controls>}); a custom {@link VideoStyle} supplies app-defined
 * control children. A poster/preview frame is a planned draft
 * ({@code POSTER_SOURCE}).
 */
public final class Video implements View, Configurable<Video.Config> {

    /** {@link Video} values. */
    public static final class Config implements View.Config {

        private MediaController controller;

        /** The controller whose video output this surface renders (spec/MEDIA.md). */
        public Config controller(MediaController controller) {
            this.controller = controller;
            return this;
        }
    }

    private final Config config;

    private Video(Config config) {
        this.config = config;
    }

    /** A video surface with no controller (renders blank/idle). */
    public static ViewBuilder<Video, Config> make() {
        return new ViewBuilder<>(new Video(new Config()));
    }

    /** A video surface rendering {@code controller}'s video output. */
    public static ViewBuilder<Video, Config> make(MediaController controller) {
        return Configurators.view(Config::new, Video::new, c -> c.controller(controller));
    }

    /** Configure the video surface's values. */
    public static ViewBuilder<Video, Config> make(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new Video(config));
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        // The surface owns the native VIDEO node; the active style supplies its
        // content as the node's child (control-owned interaction, spec DSL.md §5.7).
        // The default NativeVideoStyle supplies no content, so the node stays a leaf
        // and the renderer shows native media controls.
        PathlandNode node = new PathlandNode(Components.VIDEO);
        VideoStyle style = env.videoStyle();
        View content = style.makeBody(new VideoStyle.Configuration(config.controller));
        if (content != null && content != EmptyContent.INSTANCE) {
            node.children.add(content.render(env));
        }
        // The emitter materializes the controller's MEDIA_CONTROLLER node (by
        // object identity) and writes its id as MEDIA_CONTROLLER_ID here.
        node.mediaControllerRef = config.controller;
        return node;
    }
}
