    Toggle,
    /// Numeric range control.
    Slider,
    /// Single-line text input.
    TextField,
    /// Multi-line text input.
    TextEditor,
    /// Increment/decrement control.
    Stepper,
    /// Date & time selection.
    DatePicker,
    /// Selection control (options are children).
    Picker,
    /// Action trigger + popover container.
    Menu,
    /// Native color picker.
    ColorPicker,
}

impl core::fmt::Debug for Component {
