    public static final class Config implements View.Config {

        private Signal<DatePickerMode> mode;
        private WritableSignal<Integer> days;

        /** Set a static picker mode. */
        public Config mode(DatePickerMode mode) {
            this.mode = Signals.constant(mode);
            return this;
        }

        /** Bind the picker mode to a signal. */
        public Config mode(Signal<DatePickerMode> mode) {
            this.mode = mode;
            return this;
        }

        /** Bind the selected day (days since epoch, two-way). */
        public Config selection(WritableSignal<Integer> days) {
            this.days = days;
            return this;
        }
    }

    private final Config config;

    private DatePicker(Config config) {
        this.config = config;
    }

    /** Configure the date picker's values. */
/** An empty DatePicker (no values). */
    public static ViewBuilder<DatePicker, Config> make() {
        return new ViewBuilder<>(new DatePicker(new Config()));
    }

    public static ViewBuilder<DatePicker, Config> make(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new DatePicker(config));
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        PathlandNode node = new PathlandNode(Components.DATE_PICKER);
        if (config.mode != null) {
            node.property(Properties.DATE_PICKER_MODE, config.mode);
        }
        if (config.days != null) {
            node.days = dev.pathland.view.core.signal.Signals.untracked(config.days::get);
            node.dateBinding = config.days;
        /** Set the range bounds. */
        public Config in(float min, float max) {
            this.min = min;
            this.max = max;
            return this;
        }

        /** Report {@code EDITING_CHANGED} drag start/end boundaries. */
        public Config onEditingChanged(Consumer<Boolean> onEditingChanged) {
            this.onEditingChanged = onEditingChanged;
            return this;
        }
    }

    private final Config config;

    private Slider(Config config) {
        this.config = config;
    }

    /** Configure the slider's values. */
/** An empty Slider (no values). */
    public static ViewBuilder<Slider, Config> make() {
        return new ViewBuilder<>(new Slider(new Config()));
    }

    public static ViewBuilder<Slider, Config> make(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new Slider(config));
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        PathlandNode node = new PathlandNode(Components.SLIDER);
        if (config.binding != null) {
            node.properties.put(Properties.VALUE, dev.pathland.view.engine.ReactiveValues.initial(Properties.VALUE, config.binding));
            node.propertyBindings.put(Properties.VALUE, config.binding);
            node.valueInput = config.binding::set;
        }
        if (config.min != null) {
            node.properties.put(Properties.MIN_VALUE, config.min);
        }
        if (config.max != null) {
            node.properties.put(Properties.MAX_VALUE, config.max);
        }
        if (config.onEditingChanged != null) {
            node.properties.computeIfAbsent(Properties.EVENT_LISTENERS, k -> 0);
            node.properties.put(Properties.EVENT_LISTENERS,
                    (Integer) node.properties.get(Properties.EVENT_LISTENERS) | Commands.Listeners.EDITING);
            node.editingInput = config.onEditingChanged;
        }
        return node;
    }
}
