            this.uniform = null;
            this.top = this.right = this.bottom = this.left = null;
            return this;
        }

        /** Per-edge padding (top, right, bottom, left). */
        public Config edges(float top, float right, float bottom, float left) {
            return edges(Signals.constant(top), Signals.constant(right),
                    Signals.constant(bottom), Signals.constant(left));
        }

        /** Per-edge padding (top, right, bottom, left), each reactive. */
        public Config edges(Signal<Float> top, Signal<Float> right, Signal<Float> bottom, Signal<Float> left) {
            this.uniform = null;
            this.uniformToken = null;
            this.top = top;
            this.right = right;
            this.bottom = bottom;
            this.left = left;
            return this;
        }
    }

    private final Config config;

    private Padding(Config config) {
        this.config = config;
    }

    /** Uniform padding. */
    static Padding with(float value) {
        return Configurators.modifier(Config::new, Padding::new, c -> c.uniform(value));
    }

    /** Uniform padding (reactive). */
    static Padding with(Signal<Float> value) {
        return Configurators.modifier(Config::new, Padding::new, c -> c.uniform(value));
    }

    /** Uniform padding from a design token. */
    static Padding with(Length value) {
        return Configurators.modifier(Config::new, Padding::new, c -> c.uniform(value));
    }

    /** Configure the padding. */
    static Padding with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new Padding(config);
    }

    @Override
    public View body(View content) {
