266	private class FitSlot(private val fits: List<Fit>) : View {
267	    private val fitIndex = Signals.signal(0)
268	    private val fitReported = Signals.signal(false)
269	
270	    override fun renderNode(env: Environment): PathlandNode {
271	        val node = PathlandNode(Components.SIZE_THAT_FITS)
272	        node.properties[Properties.FIT_QUERY] = FloatArray(fits.size) { fits[it].minWidth }
273	        val hint = Emitter.current()?.currentSlotOldFitSelection()
274	        if (hint != null && hint != fitIndex.get()) {
275	            Signals.untracked { fitIndex.set(hint); null }
276	        }
277	        val index = fitIndex.get().coerceIn(0, (fits.size - 1).coerceAtLeast(0))
278	        node.fitSelection = index
279	        node.fitReported = fitReported.get()
280	        node.fitInput = Consumer { incoming ->
281	            if (incoming != null && incoming in fits.indices) {
282	                node.fitReported = true
283	                node.fitSelection = incoming
284	                fitIndex.set(incoming)
285	                fitReported.set(true)
286	            }
287	        }
288	        if (PathlandNode.SNAPSHOT_EMISSION.get() && !fitReported.get()) {
289	            fits.forEach { node.children.add(it.view.render(env)) }
290	        } else {
291	            fits.getOrNull(index)?.let { node.children.add(it.view.render(env)) }
292	        }
293	        return node
294	    }
295	}
