297	private fun sizeThatFits(fits: Array<Fit>): View {
298	    val sorted = fits.sortedBy { it.minWidth }
299	    for (i in sorted.indices) {
300	        for (j in i + 1 until sorted.size) {
301	            check(sorted[i].view !== sorted[j].view) {
302	                "a View instance can be used as the candidate of at most one SizeThatFits Fit"
303	            }
304	        }
305	    }
306	    return FitSlot(sorted).registerChild()
307	}
